-- ROLLBACK of db/pg_backlog/30_transitions.sql (FND-0331, step A-1). Run by scripts/ops/migrate_backlog_v2.py --phase transitions --down --apply
-- (dry run without --apply). The script first re-creates the LEGACY sp_close_release (block backlog_sp_close_release of 10_kpis_and_release.sql, so
-- it is not duplicated here) and then runs the block below, in the same transaction.
--
-- What is lost: the status_event / wait_event / raw_update_event rows (the BACKFILL events can be regenerated by re-applying A-1; live events cannot).
-- Tickets, logs and link events are never touched, EXCEPT the link events and OPT tickets the routines themselves created, which stay (they are
-- history). Run the acceptance script's --baseline BEFORE and --verify AFTER if the history must be proven unchanged.
--
-- Refused while step A-2 is applied: with direct INSERT/UPDATE revoked from backlog_writer, going back to the legacy routines would leave every
-- writer without a way to write. Roll A-2 back first (--phase revoke --down --apply).

-- BEGIN backlog_transitions_down
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'backlog_writer')
       AND NOT has_table_privilege('backlog_writer', 'backlog.backlog', 'UPDATE') THEN
        RAISE EXCEPTION 'step A-2 is still applied (backlog_writer cannot UPDATE backlog.backlog): roll back --phase revoke first';
    END IF;
END $$;

DROP TRIGGER IF EXISTS governed_writes ON backlog.BACKLOG;
DROP VIEW IF EXISTS backlog.v_shadow_stage;
DROP FUNCTION IF EXISTS backlog.sp_transition(text, text, text, text, text, text, text, text, text, date, text, text, text, boolean);
DROP FUNCTION IF EXISTS backlog.sp_open_ticket(text, text, text, text, text, text, text, text, text, text, text);
DROP FUNCTION IF EXISTS backlog.trg_governed_writes();
DROP FUNCTION IF EXISTS backlog.fn_transition_legal(text, text);
DROP FUNCTION IF EXISTS backlog.fn_actor_ok(text);
DROP TABLE IF EXISTS backlog.raw_update_event;
DROP TABLE IF EXISTS backlog.wait_event;
DROP TABLE IF EXISTS backlog.status_event;
DROP FUNCTION IF EXISTS backlog.trg_append_only();

-- The legacy procedure was re-created by the script just before; give it back to the role that applies DDL, then remove the owner role.
ALTER PROCEDURE backlog.sp_close_release(text, text, boolean) OWNER TO CURRENT_USER;
REVOKE ALL ON SCHEMA backlog FROM backlog_owner;
DROP OWNED BY backlog_owner;
DROP ROLE IF EXISTS backlog_owner;
-- END backlog_transitions_down
